202		}
203		wantSummaries := []struct {
204			period Month
205			due    int64
206		}{
207			{jan(2026), 1320},
208			{feb(2026), 3300},
209			{apr(2026), 4800},
210		}
211		if len(st.Bills) != len(wantSummaries) {
